function showRemoteRecovery(remote){if(!remote.state)return;let panel=$('remoteRecovery');if(!panel){panel=document.createElement('div');panel.id='remoteRecovery';panel.className='panel';$('syncRetry').before(panel);}panel.innerHTML='<h3>Hay una versión actualizada en Google</h3><p>Podés cargarla conservando una copia de los cambios de este dispositivo.</p><button class="button primary" type="button">Cargar versión de Google y guardar copia local</button>';panel.querySelector('button').onclick=async()=>{try{const response=await fetch('./api/state',{cache:'no-store'}),fresh=await apiJSON(response);if(!response.ok||!fresh.state)throw Error(fresh.error||'No se pudo leer Google');const backup={app:'Sasha Control de cajas',exportedAt:new Date().toISOString(),data:state};localStorage.setItem('sashaConflictBackup',JSON.stringify(backup));download('control-cajas-respaldo-antes-de-actualizar.json',JSON.stringify(backup),'application/json');state=normalizeState(fresh.state);revision=fresh.revision;online=true;localStorage.setItem('sashaControlCajasV1',JSON.stringify(state));localStorage.setItem('cajasRevision',revision);localStorage.removeItem('cajasPending');panel.remove();render();msg('Versión de Google cargada. Tu copia anterior quedó respaldada.',true);}catch(e){msg(e.message);}};}
function msg(s,ok=false){clearTimeout(messageTimer);clearTimeout(messageExitTimer);$('message').textContent=s;$('message').className=s?'notice '+(ok?'success':''):'';let toast=$('saveToast');if(!toast){toast=document.createElement('div');toast.id='saveToast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');document.body.append(toast);}toast.textContent=s;toast.className='save-toast '+(ok?'success':'notice');toast.hidden=!s;toast.classList.remove('toast-exit');$('message').hidden=!s;if(s){messageTimer=setTimeout(()=>{toast.classList.add('toast-exit');$('message').hidden=true;messageExitTimer=setTimeout(()=>{toast.hidden=true;toast.textContent='';$('message').textContent='';},300);},5000);}const pending=localStorage.getItem('cajasPending')==='true';$('syncRetry').textContent=pending?'Cambios locales pendientes · Reintentar sincronización':'Reintentar sincronización con Google';for(const el of [$('message'),toast]){if(s&&!ok){el.dataset.noticeTarget=/cupon|electrónico|acredit|reparto/i.test(s)?'coupons':'files';el.dataset.noticeDate=s.match(/\d{4}-\d{2}-\d{2}/)?.[0]||$('date').value;el.dataset.noticeText=s;el.setAttribute('role','button');el.tabIndex=0;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};}else{delete el.dataset.noticeTarget;delete el.dataset.noticeDate;delete el.dataset.noticeText;el.removeAttribute('tabindex');el.onkeydown=null;}}}
const sales=()=>paymentRows(state),closes=()=>dailyCloses(state);
const card=(title,value,detail='',status='')=>`<div class="card ${status}"><span class="label">${title}</span><strong>${value}</strong><small>${detail}</small></div>`;
const signedMoney=n=>`<b class="${n<0?'bad':n>0?'good':''}">${money(n)}</b>`;
const balanceCard=(title,n,detail='')=>card(title,n===null?'—':money(n),detail+(n===null?'':`<span class="metric-state">${n<0?'Saldo negativo':n>0?'Saldo positivo':'Sin diferencia'}</span>`),n===null?'':n<0?'metric-negative':'metric-positive');
function goalCard(title,n,key,detail='',count=false){const goal=state.metricGoals[key];if(n===null||!goal)return card(title,n===null?'—':count?n:money(n),detail);const met=n>=goal,percent=Math.round(n/goal*100);return card(title,count?n:money(n),detail+`<span class="goal-caption">Objetivo ${count?goal:money(goal)}</span><span class="metric-state">${met?'✓ Objetivo cumplido':'Por debajo del objetivo'} · ${percent} %</span><progress class="goal-progress" max="100" value="${Math.max(0,Math.min(100,percent))}" aria-label="${esc(title)}: ${percent} % del objetivo"></progress>`,met?'metric-positive':'metric-negative');}
const goalFields=[['monthlyRevenue','Facturación mensual ($)'],['dailyRevenue','Facturación diaria ($)'],['monthlyTickets','Tickets mensuales'],['dailyTickets','Tickets diarios'],['monthlyAverage','Ticket promedio mensual ($)'],['dailyAverage','Ticket promedio diario ($)']];
function drawGoals(){$('goalFields').innerHTML=goalFields.map(([key,label])=>`<label>${label}<input name="${key}" inputmode="decimal" value="${state.metricGoals[key]?key.includes('Tickets')?state.metricGoals[key]:(state.metricGoals[key]/100).toFixed(2).replace('.',','):''}" placeholder="Sin objetivo"></label>`).join('');}
