function warningNotice(text,date){return text.startsWith('Control de apertura:')?actionNotice(text,date):`<p class="notice info"><strong>Información · No requiere completar datos</strong><br>${esc(text)}</p>`;}
function actionNotice(text,date){const target=/comprobante del gasto/i.test(text)?'expenses':/cupon|electrónico|acredit|repartir|reparto/i.test(text)?'coupons':/apertura|cierre|horario|asignar|cajera/i.test(text)?'continuity':/producto|ticket|comprobante|crédito|anulaci/i.test(text)?'products':'files';return `<button type="button" class="notice notice-action" data-notice-target="${target}" data-notice-date="${esc(date)}" data-notice-text="${esc(text)}">${esc(text)}<strong>Ir a revisar →</strong></button>`;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-notice-target]');if(!button)return;const {noticeTarget:target,noticeDate:date,noticeText:text}=button.dataset;let destination;if(target==='expenses'){openSection('expenses');destination=$('expenseHistory');}else if(target==='products'){openSection('products');$('productsMonth').value=date.slice(0,7);$('productsDate').value=date;drawProducts();destination=$('productRecords');}else if(target==='files'){openSection('files');$('filesDate').value=date;drawFileChecklist();destination=$('fileChecklist');}else{document.querySelector('[data-tab="day"]').click();$('date').value=date;$('box').value='';$('dayCashier').value='';drawDay();if(target==='coupons'){destination=$('couponForm')||$('couponSummary');const batch=text.match(/Vuelco (\d+)|turno (\d+)/i);if(batch)destination=[...$('day').querySelectorAll('[data-coupon-turn]')].find(el=>el.dataset.couponTurn.endsWith('|'+(batch[1]||batch[2])))||destination;}else{const alert=operationalAlerts(state,date).find(a=>!a.reviewed&&text.includes(a.cashier)&&text.includes(a.box)&&(!/Vuelco \d+/.test(text)||text.includes('Vuelco '+a.batch)));destination=alert?[...$('day').querySelectorAll('[data-review-alert]')].find(el=>el.dataset.reviewAlert===alert.key):null;destination||=$('day').querySelector('[data-continuity-panel]');}}if(destination){for(let el=destination.parentElement;el;el=el.parentElement)if(el.tagName==='DETAILS')el.open=true;const inner=destination.querySelector('details.report-detail');if(inner)inner.open=true;destination.scrollIntoView({behavior:'smooth',block:'start'});destination.classList.add('action-highlight');setTimeout(()=>destination.classList.remove('action-highlight'),2500);}});
function guidedPanel(date){
 const questions=guidedQuestions(state,date),moneyInput=q=>`<label>Importe correcto<input data-guided-amount inputmode="decimal" autocomplete="off" placeholder="Ej.: 234674,00" required></label><label>Observación (opcional)<input data-guided-note maxlength="500" placeholder="Qué verificaste"></label><button type="button" class="button primary" data-guided-save>Guardar respuesta y recalcular</button>`;
 return questions.length?`<section aria-label="Preguntas para cerrar el día"><h3>Respondé para continuar</h3><p>Elegí el importe que verificaste o ingresá otro. Cada respuesta recalcula el saldo.</p>${questions.map(q=>`<div class="panel" data-guided-key="${esc(q.key)}">${q.kind==='payment'?`<h3>¿Cuánto recibió ${esc(q.cashier)} por ${esc(q.label)}?</h3><p>Caja ${esc(q.box)} · Cierre ${esc(q.batch)}</p><div class="actions"><button type="button" class="button" data-guided-pick="${q.entered}">Declaración de la cajera: ${money(q.entered)}</button><button type="button" class="button" data-guided-pick="${q.pdf}">Informe PDF: ${money(q.pdf)}</button></div><p>Diferencia: <strong>${money(Math.abs(q.pdf-q.entered))}</strong>. Verificá la acreditación antes de elegir.</p>${moneyInput(q)}`:q.kind==='opening'?`<h3>¿Con cuánto efectivo abrió ${esc(q.cashier)} la caja ${esc(q.box)}?</h3><div class="actions"><button type="button" class="button" data-guided-pick="${q.entered}">Apertura del PDF: ${money(q.entered)}</button><button type="button" class="button" data-guided-pick="${q.expected}">Quedó del cierre anterior: ${money(q.expected)}</button></div><p>Elegí el efectivo que realmente recibió al abrir.</p>${moneyInput(q)}`:q.kind==='closing'?`<h3>${esc(q.cashier)} · Caja ${esc(q.box)}: ${q.net<0?'faltan':'sobran'} ${money(Math.abs(q.net))}</h3><p>¿Verificaste esta diferencia? Aceptarla la deja registrada; no cambia el dinero ni la lleva a cero.</p><label>¿Qué verificaste?<textarea data-guided-note maxlength="500" required placeholder="Explicá el motivo o la revisión realizada"></textarea></label><div class="actions"><button type="button" class="button primary" data-guided-save>Aceptar diferencia revisada</button><button type="button" class="button" data-notice-target="continuity" data-notice-date="${date}" data-notice-text="${esc(q.cashier)} Caja ${q.box} Vuelco ${q.batch}">Corregir un importe</button></div>`:`<h3>¿Corroboraste las acreditaciones de los turnos?</h3><p>El total cargado coincide con los cupones del día. Confirmá que verificaste los importes recibidos.</p><button type="button" class="button primary" data-guided-save>Sí, corroboré los cupones</button>`}</div>`).join('')}<p>El día se confirma al final, con el botón «Confirmar control completo».</p></section>`:'';
}
function bindGuidedReview(){
 document.querySelectorAll('[data-guided-key]').forEach(el=>{
  el.querySelectorAll('[data-guided-pick]').forEach(b=>b.onclick=()=>{el.querySelector('[data-guided-amount]').value=(Number(b.dataset.guidedPick)/100).toFixed(2).replace('.',',');el.querySelector('[data-guided-amount]').focus();});
  el.querySelector('[data-guided-save]').onclick=()=>{try{const input=el.querySelector('[data-guided-amount]');if(input&&!input.value.trim())throw Error('Elegí o ingresá el importe correcto.');state=answerGuidedQuestion(state,el.dataset.guidedKey,input?cents(input.value):null,el.querySelector('[data-guided-note]')?.value||'');save('Respuesta guardada · Saldo recalculado');$('requiredReports')?.closest('.panel')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){msg(e.message);}};
 });
}
function statusPanel(d){if(!d)return '';const st=controlStatus(state,d),questions=guidedQuestions(state,d),remaining=st.issues.filter(x=>!questions.length||!(/Completá y corroborá los cupones|Revisión de cierre pendiente:|Control de apertura:/.test(x)));if(st.closed&&!st.issues.length)return `<div class="panel"><h2>Día sin actividad · Local cerrado</h2><p>${esc(state.closedDays.find(r=>r.date===d)?.reason||'Domingo')}. No se requieren PDF, cupones ni confirmación del día.</p></div>`;return `<div class="panel"><h2>Archivos del día · ${st.received}/${st.expected} requeridos</h2><p class="${st.complete?'good':'bad'}">${st.complete?(st.warnings.length?'Revisión completa. Podés confirmar el día; las observaciones quedan registradas.':'Archivos completos y totales conciliados.'):'Revisemos el día: respondé las preguntas de abajo.'}</p><details id="requiredReports" ${st.received<st.expected||st.required.some(r=>r.duplicate||r.unassigned)?'open':''}><summary>Ver informes requeridos · ${st.received}/${st.expected} cargados</summary>${table(['Informe requerido','Estado','Archivo'],st.required.map(r=>[esc(r.label),r.present?'<strong class="status-ok">✓ Cargado</strong>':r.duplicate?'Duplicado':r.unassigned?'Cargado · Falta asignar cajera':'Falta descargar',esc(r.filename||'—')]))}<p>Resumen diario: ${st.optional.length?'cargado para contrastar':'opcional; los cierres ya contienen sus datos'}.</p></details>${guidedPanel(d)}${remaining.length?'<h3>También falta revisar</h3>'+remaining.map(x=>actionNotice(x,d)).join(''):''}${st.warnings.length?'<details><summary>Ver observaciones de los informes ('+st.warnings.length+')</summary>'+st.warnings.map(x=>warningNotice(x,d)).join('')+'</details>':''}<button class="button primary" id="completeDay" ${st.complete?'':'disabled'}>${state.completedDays.includes(d)&&st.complete?'Día confirmado':'Confirmar control completo'}</button></div>`;}

// ---- Sasha v94: control del día por pasos (modelo C). Cuando el día queda confirmado, los pasos se esconden
// (un link chico "Día confirmado · editar") y queda el resumen.
const pasosAbiertos={};
const MESES=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
