 $('restore').onchange=async e=>{try{const backup=JSON.parse(await e.target.files[0].text());if(backup.app!=='Sasha Control de cajas'||!Array.isArray(backup.data?.reports)||!Array.isArray(backup.data?.manual))throw Error('Respaldo no válido');for(let r of backup.data.reports){if(!['sales','close','turnClose','tickets'].includes(r.type)||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Array.isArray(r.rows))throw Error('Reporte no válido');for(let row of r.rows){let keys=['sales','tickets'].includes(r.type)?['amount']:['opening','sales','withdrawals','cash','digital'];if(keys.some(k=>!Number.isSafeInteger(row[k])))throw Error('Importes no válidos')}}if(confirm('¿Restaurar este respaldo? Reemplaza los datos de este navegador.')){state=normalizeState(backup.data);save();msg('Respaldo restaurado')}}catch(err){msg(err.message)}e.target.value=''};
 $('csv').onclick=()=>{let rows=[['Fecha','Sucursal','Caja','Ventas','Tickets','Efectivo etiqueta PDF no confirmado','Electronico etiqueta PDF no confirmado','Diferencia cierre']];for(let [key,r]of groups([...sales(),...closes()],r=>`${r.date}|${r.branch}|${r.box}`)){let [d,b,c]=key.split('|'),ss=sales().filter(r=>r.date===d&&r.branch===b&&r.box===c),cc=closes().filter(r=>r.date===d&&r.branch===b&&r.box===c),s=summarize(ss);rows.push([d,b,c,(ss.length?s.total:cc.reduce((a,x)=>a+x.sales,0))/100,ss.length?s.tickets:'',ss.length?s.cash/100:'',ss.length?s.digital/100:'',cc.length?cc.reduce((a,x)=>a+difference(x),0)/100:''])}download('control-cajas.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8')};$('syncRetry').onclick=()=>{syncFailures=0;clearTimeout(syncRetryTimer);syncGoogle();};window.addEventListener('online',()=>{if(online&&localStorage.getItem('cajasPending')==='true')syncGoogle();});
