$('cashierForm').onsubmit=e=>{e.preventDefault();const name=$('cashierName').value.trim(),start=$('cashierStart').value,end=$('cashierEnd').value;if(!name||start>=end)return msg('Revisá el nombre y el horario de la cajera');const id=$('cashierId').value||crypto.randomUUID(),record={...(state.cashiers.find(c=>c.id===id)||{activeFrom:new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Argentina/Buenos_Aires'}).format(new Date())}),id,name,shift:$('cashierShift').value,start,end,active:true};const idx=state.cashiers.findIndex(c=>c.id===id);if(idx>=0)state.cashiers[idx]=record;else state.cashiers.push(record);$('cashierForm').reset();$('cashierId').value='';save();};
