function expensesPanel(date){const rows=storeExpenses(state,date),total=rows.reduce((sum,e)=>sum+e.amount,0),pending=rows.filter(e=>!e.receipt).length;const detail=items=>`${items.length?items.map(e=>`<div class="panel"><b>${esc(e.description)} · ${money(e.amount)}</b><p>${fmt(e.date)} · ${esc(e.cashier)} · Caja ${esc(e.box)} · Vuelco ${esc(e.batch)}</p>${e.receipt?`<p class="notice success">✓ Comprobante guardado: ${esc(e.receipt.name)}</p><a class="button" href="./api/expense-receipt?id=${esc(e.receipt.id)}" target="_blank" rel="noopener">Descargar comprobante</a>`:(e.box==='0003'?'<p>Comprobante opcional · Gasto registrado sin foto.</p>':'<p class="notice">Obligatorio: falta adjuntar el comprobante.</p>')}<div class="actions"><label class="button">Sacar foto<input type="file" accept="image/*" capture="environment" data-expense-upload="${esc(e.key)}" hidden></label><label class="button">${e.receipt?'Reemplazar comprobante':'Adjuntar foto o PDF'}<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" data-expense-upload="${esc(e.key)}" hidden></label></div><div data-expense-photo-status aria-live="polite"></div></div>`).join(''):'<p>No hay gastos detectados en los cierres de este período.</p>'}`;const months=groups(rows,e=>e.date.slice(0,7)).sort(([a],[b])=>b.localeCompare(a));return `<div class="panel" data-expenses-panel><h2>Gastos del local${date?' · '+fmt(date):''}</h2><div class="cards">${card(date?'Total de gastos del día':'Total de gastos registrados',money(total))}${card('Gastos registrados',rows.length)}${card('Comprobantes pendientes',pending,pending?'Falta adjuntar foto o PDF':'Todos los gastos tienen comprobante')}</div><p>Las líneas GASTO del cierre se registran separadas de los alivios. El gasto ya está incluido en los movimientos de efectivo: no se descuenta nuevamente. En caja 3, la foto o PDF es opcional y su ausencia no impide confirmar el día.</p>${date?detail(rows):months.length?months.map(([month,items],index)=>`<details class="expense-month" ${index===0?'open':''}><summary><span>${esc(new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'-01T12:00:00Z')))}</span><strong>${money(items.reduce((sum,e)=>sum+e.amount,0))}</strong></summary><p>${items.length} gastos · ${items.filter(e=>!e.receipt).length} comprobantes pendientes</p>${detail(items)}</details>`).join(''):'<p>No hay gastos registrados.</p>'}</div>`;}
async function receiptFile(file){let data,mime=file.type||(/\.pdf$/i.test(file.name)?'application/pdf':/\.(jpe?g|png|webp|heic|heif)$/i.test(file.name)?'image/jpeg':'');if(mime.startsWith('image/')){let image,url;try{try{image=await createImageBitmap(file);}catch{url=URL.createObjectURL(file);image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('No se pudo leer la foto. Probá adjuntarla desde la galería en JPG'));img.src=url;});}const width=image.naturalWidth||image.width,height=image.naturalHeight||image.height,scale=Math.min(1,1400/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);for(const quality of [.82,.65,.5]){data=canvas.toDataURL('image/jpeg',quality).split(',')[1];if(data.length<=1400000)break;}if(!data||data.length>2800000)throw Error('La foto es demasiado grande. Probá con otra foto');mime='image/jpeg';}finally{image?.close?.();if(url)URL.revokeObjectURL(url);}}else if(mime==='application/pdf'){if(file.size>2097152)throw Error('El PDF debe ser de hasta 2 MB');data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('No se pudo leer el archivo'));reader.readAsDataURL(file);});}else throw Error('Adjuntá una foto JPG, PNG, WebP o PDF');return {data,mime,name:(mime==='image/jpeg'?(file.name||'comprobante').replace(/\.[^.]+$/, '')+'.jpg':file.name).slice(0,200)};}
async function uploadReceipt(payload){for(let attempt=0;attempt<3;attempt++){try{const response=await fetch('./api/expense-receipt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),result=await apiJSON(response);if(!response.ok){const err=Error(result.error||'No se pudo guardar el comprobante');err.transient=[429,502,503,504].includes(response.status);throw err;}if(!result.receipt)throw Error('No se confirmó el guardado de la foto');return result.receipt;}catch(error){if(attempt===2||!(error.transient||error instanceof TypeError))throw error;await new Promise(resolve=>setTimeout(resolve,1500*(attempt+1)));}}}
function bindExpenses(){document.querySelectorAll('[data-expense-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;const key=input.dataset.expenseUpload,panel=input.closest('.panel'),status=panel.querySelector('[data-expense-photo-status]'),inputs=panel.querySelectorAll('[data-expense-upload]');let payload;const run=async()=>{inputs.forEach(i=>i.disabled=true);try{status.innerHTML='<p class="notice">Preparando y guardando comprobante…</p>';payload ||= await receiptFile(file);status.innerHTML=(payload.mime.startsWith('image/')?`<img alt="Foto del comprobante seleccionado" src="data:${payload.mime};base64,${payload.data}" style="max-width:100%;max-height:220px;object-fit:contain">`:'')+'<p class="notice">Foto seleccionada · Guardando en Google…</p>';const receipt=await uploadReceipt(payload),expense=storeExpenses(state).find(e=>e.key===key);if(!expense)throw Error('El gasto cambió; revisá el cierre actualizado');state.expenseReceipts=state.expenseReceipts.filter(r=>r.expenseKey!==key);state.expenseReceipts.push({...receipt,expenseKey:key});state.completedDays=state.completedDays.filter(d=>d!==expense.date);save('✓ Comprobante del gasto guardado');}catch(e){status.innerHTML=(payload?.mime.startsWith('image/')?`<img alt="Foto pendiente de guardar" src="data:${payload.mime};base64,${payload.data}" style="max-width:100%;max-height:220px;object-fit:contain">`:'')+`<p class="notice">No se guardó el comprobante: ${esc(e.message)}. El gasto sigue pendiente.</p><button type="button" class="button" data-retry-photo>Reintentar guardar foto</button>`;status.querySelector('[data-retry-photo]').onclick=run;msg('No se pudo guardar el comprobante: '+e.message);}finally{inputs.forEach(i=>i.disabled=false);input.value='';}};await run();});}
function filteredProducts(){const month=$('productsMonth').value,date=$('productsDate').value,box=$('productsBox').value,cashier=$('productsCashier').value,query=$('productSearch').value.trim().toLocaleLowerCase('es');return productLines(state).filter(r=>(!month||r.date.startsWith(month))&&(!date||r.date===date)&&(!box||r.box===box)&&(!cashier||(cashier==='unassigned'?!r.cashierId:r.cashierId===cashier))&&(!query||(r.code+' '+r.name).toLocaleLowerCase('es').includes(query)));}
function drawProducts(){const box=$('productsBox').value,cashier=$('productsCashier').value;$('productsBox').innerHTML='<option value="">Todas</option>'+[...new Set(productLines(state).map(r=>r.box))].sort().map(b=>`<option>${esc(b)}</option>`).join('');$('productsBox').value=box;$('productsCashier').innerHTML='<option value="">Todas</option><option value="unassigned">Sin asignar</option>'+state.cashiers.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('productsCashier').value=cashier;const rows=filteredProducts(),ranks=rankProducts(rows).sort((a,b)=>b[$('productSort').value]-a[$('productSort').value]||a.code.localeCompare(b.code)),net=rows.reduce((a,r)=>a+r.net,0),gross=rows.reduce((a,r)=>a+r.gross,0),units=rows.reduce((a,r)=>a+r.quantity,0),keys=new Set(rows.map(receiptKey));const pendingDates=[...new Set(rows.map(r=>r.date))].filter(d=>!ticketTotalsConfirmed(state,d));$('productMetrics').innerHTML=(pendingDates.length?`<p class="notice">Detalle de productos pendiente de conciliación (${pendingDates.map(fmt).join(', ')}). Puede incluir notas de crédito o anulaciones. Los importes y unidades del ranking conservan el PDF y requieren corroboración; la facturación del inicio usa los cierres.</p>`:'')+`<div class="cards">${card('Unidades',units)}${card('Productos distintos',ranks.length)}${card('Ventas netas prorrateadas',money(net))}${card('Descuento prorrateado',money(gross-net),'Puede incluir redondeo')}</div>`;$('productRanking').innerHTML=`<div class="panel"><h2>Ranking de productos</h2>${ranks.length?table(['Puesto','Código','Producto','Unidades','Venta neta estimada','Tickets','Precio neto medio'],ranks.map((r,i)=>[i+1,esc(r.code),esc(r.name),r.units,money(r.net),r.tickets,money(r.averageUnit)])):'<p class="empty">Importá el detalle de tickets con productos de este período.</p>'}<p>El catálogo contiene productos vendidos. No representa stock ni permite calcular ganancia sin costos.</p></div>`;const last=rows.slice().sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).slice(0,500);$('productRecords').innerHTML=`<div class="panel"><h2>Registro de ventas de productos</h2><p>${last.length} de ${rows.length} líneas. El registro completo se guarda en Google Sheets y en la exportación.</p>${table(['Día','Hora','Caja','Ticket','Cajera','Código','Producto','Unidades','Bruto','Neto estimado'],last.map(r=>[fmt(r.date),esc(r.time),esc(r.box),esc(r.ticket),esc(r.cashier),esc(r.code),esc(r.name),r.quantity,money(r.gross),money(r.net)]))}</div>`;const tickets=ticketRows(state).filter(t=>keys.has(receiptKey(t)));$('ticketRecords').innerHTML=`<div class="panel"><h2>Tickets y horarios</h2>${table(['Día','Hora','Caja','Ticket','Cajera','Unidades','Total','Descuento','Criterio'],tickets.slice(0,500).map(t=>{const a=assign(state,t);return [fmt(t.date),esc(t.time),esc(t.box),esc(t.ticket),esc(a.name),t.items.reduce((s,x)=>s+x.quantity,0),money(t.amount),esc(t.discountPercent)+'%',esc(a.basis)];}))}<p>Los tickets se cuentan una sola vez, aunque tengan varios productos o medios de pago.</p></div>`;}
function drawFileControls(){const old=$('filesDate').value,dates=[...new Set(state.reports.map(r=>r.date))].sort().reverse();$('filesDate').innerHTML=dates.map(d=>`<option value="${d}">${fmt(d)}</option>`).join('');if(dates.includes(old))$('filesDate').value=old;drawFileChecklist();}
function drawFileChecklist(){const d=$('filesDate').value;if(!d){$('fileChecklist').innerHTML='<p>No hay reportes importados.</p>';return;}const st=controlStatus(state,d);$('fileChecklist').innerHTML=`<p><b>${st.received}/${st.expected} archivos requeridos</b> · ${st.complete?'Control completo':'Pendiente'}</p>${table(['Informe','Estado','Archivo'],st.required.map(r=>[esc(r.label),r.present?'<strong class="status-ok">✓ Cargado</strong>':r.duplicate?'Duplicado':r.unassigned?'Cargado · Falta asignar cajera':'Falta descargar',esc(r.filename||'—')]))}<p>Resumen diario: ${st.optional.length?'cargado · '+esc(st.optional.map(r=>r.filename).join(' / ')):'opcional, puede omitirse'}.</p>${st.issues.map(x=>actionNotice(x,d)).join('')}${st.warnings.map(x=>warningNotice(x,d)).join('')}`;}
function exportProducts(){const rows=[['Fecha','Hora','Sucursal','Caja','Ticket','Cajera','Codigo','Producto','Unidades','Bruto','Neto prorrateado','Bonificacion %','Descuento ticket %'],...filteredProducts().map(r=>[r.date,r.time,r.branch,r.box,r.ticket,r.cashier,r.code,r.name,r.quantity,r.gross/100,r.net/100,r.bonusPercent,r.discountPercent])];download('control-cajas-productos.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');}

function couponSummary(date,st){const r=st.review;return `<div class="panel" id="couponSummary"><h2>Cupones del día</h2><p class="notice success">${st.autoReconciled?'✓ Mercado Pago y Cuenta DNI conciliados automáticamente con el PDF':'✓ Reparto corroborado y guardado'}</p><div class="coupon-summary">${[['Mercado Pago',r.mercadoPago],['Cuenta DNI',r.cuentaDni],['Otros electrónicos',r.other],['Pedidos a cobrar',st.pendingOrders],['No efectuados incluidos',st.failed],['Por conciliar',st.remaining]].filter(([label,n])=>n||['Mercado Pago','Cuenta DNI','Por conciliar'].includes(label)).map(([label,n])=>`<div><span>${label}</span><b>${money(n)}</b></div>`).join('')}</div><details><summary>Ver reparto por caja y turno</summary>${table(['Cajera','Caja','Vuelco','Mercado Pago','Cuenta DNI','Otros','Pedidos'],allTurns(state,date).map(t=>{const a=turnCollection(state,t).allocation;return [esc(assign(state,t,'close').name),esc(t.box),esc(t.batch),money(a.mercadoPago),money(a.cuentaDni),money(a.other),money(a.pendingOrders||0)];}))}</details>${r.note&&!st.autoReconciled?`<p>${esc(r.note)}</p>`:''}<button type="button" class="button" id="editCouponSummary">Editar declaración</button></div>`;}
function couponPanel(date){if(!date)return '';if(!allTurns(state,date).length&&visibleTeamDeclarations(state,date).length)return pendingTeamCoupons(date);const st=couponStatus(state,date);if(st.complete&&!couponEditing.has(date))return couponSummary(date,st);const r=st.review||{},turns=allTurns(state,date).filter(t=>t.box==='0001').sort((a,b)=>(a.openTime+a.box).localeCompare(b.openTime+b.box)),options=selected=>'<option value="">Sin cierre asignado</option>'+turns.map(t=>`<option value="${esc([t.branch,t.box,t.batch].join('|'))}" ${selected===[t.branch,t.box,t.batch].join('|')?'selected':''}>${esc(assign(state,t,'close').name)} · Caja ${esc(t.box)} · Vuelco ${esc(t.batch)}</option>`).join(''),val=n=>((n||0)/100).toFixed(2).replace('.',','),reference=r.dailyReference||(!r.allocations?{mercadoPago:r.mercadoPago,cuentaDni:r.cuentaDni,other:r.other}:null);return `<div class="panel"><h2>Cobros por cajera, turno y caja</h2>${st.complete?'<p class="notice success" data-coupon-saved>✓ Reparto corroborado y guardado</p>':''}<p>Desde el 16/10/2026, M PAGO OFF declarado corresponde a Mercado Pago y Cupones declarados a Cuenta DNI. Si coinciden con el envío de la cajera, se concilian automáticamente. Contrastá con las acreditaciones de Mercado Pago y Cuenta DNI. Los medios del PDF de detalles no confirman cómo se cobró. No incluyas cobros no efectuados en los importes acreditados. Cargá cada turno: los totales del día se calculan solos.</p>${reference&&Number.isSafeInteger(reference.mercadoPago)?'<p class="notice">Referencia diaria guardada: Mercado Pago '+money(reference.mercadoPago)+' · Cuenta DNI '+money(reference.cuentaDni)+' · Otros '+money(reference.other)+'. El reparto por turno se verifica abajo.</p>':''}<div class="cards">${card('Cupones declarados',st.dailyComplete?'<strong class="status-ok">'+money(st.declared)+'</strong>':money(st.declared),esc(st.declaredBasis))}${card('Acreditaciones ingresadas',st.dailyComplete?'<strong class="status-ok">'+money(st.credited)+'</strong>':money(st.credited))}${card('Pedidos pendientes de cobro',money(st.pendingOrders),'Ventas pendientes de cobro · No son faltantes')}${card('Cobros no efectuados incluidos',money(st.failed))}${card('Por conciliar',withinTolerance(st.remaining)?'<strong class="status-ok">'+money(st.remaining)+'</strong>':money(st.remaining),st.complete?'<strong class="status-ok">✓ Corroborado por turno</strong>':st.dailyComplete?'<strong class="status-ok">✓ Total conciliado</strong> · Reparto pendiente':'Pendiente de corroboración')}</div><form id="couponForm"><h3>Totales del día · calculados automáticamente</h3><p>Se suman los importes que declarás por caja y turno. No tenés que volver a cargarlos.</p><div class="formgrid"><div><span class="label">Mercado Pago</span><strong class="coupon-total" id="couponMPDisplay">${money(r.mercadoPago||0)}</strong><input id="couponMP" type="hidden" value="${val(r.mercadoPago)}"></div><div><span class="label">Cuenta DNI</span><strong class="coupon-total" id="couponDNIDisplay">${money(r.cuentaDni||0)}</strong><input id="couponDNI" type="hidden" value="${val(r.cuentaDni)}"></div><div><span class="label">Otros electrónicos</span><strong class="coupon-total" id="couponOtherDisplay">${money(r.other||0)}</strong><input id="couponOther" type="hidden" value="${val(r.other)}"></div><label>Referencia / observaciones<input id="couponNote" maxlength="500" value="${esc(r.note||'')}"></label></div><h3>Importes por turno</h3><p>Si un pedido online o envío se facturó, pero se cobra al entregar, ingresalo como pedido a cobrar en su caja y turno. No lo cargues como acreditación ni cobro fallido.</p>${turns.map(t=>{const a=r.allocations?.find(a=>turnKey(a)===turnKey(t));return `<div class="panel" data-coupon-turn="${esc(turnKey(t))}"><h3>${esc(assign(state,t,'close').name)} · ${esc(t.openTime||'')} a ${esc(t.closeTime||'')} · Caja ${esc(t.box)}</h3><p>Vuelco ${esc(t.batch)} · Ventas ${money(t.sales)} · Cupones PDF ${money(t.digital)}</p><div class="formgrid">${[['mercadoPago','Mercado Pago'],['cuentaDni','Cuenta DNI'],['other','Otros electrónicos'],['pendingOrders','Pedidos facturados pendientes de cobro']].map(([k,label])=>`<label>${label}${k==='pendingOrders'?'':' acreditado'} ($)<input data-allocation="${k}" inputmode="decimal" required placeholder="0,00" value="${a?val(a[k]||0):['other','pendingOrders'].includes(k)?'0,00':''}"></label>`).join('')}</div><div data-turn-preview></div></div>`;}).join('')}<div id="couponDraftPreview" aria-live="polite"></div><h3>Cobros no efectuados</h3>${st.failures.map(f=>`<div class="panel" data-failure="${esc(f.id)}"><b>${esc(f.method)} · ${money(f.amount)}</b><p>${esc(f.note)} · Ticket ${esc(f.ticket||'sin referencia')}</p><label>Cierre responsable<select data-failure-close>${options([f.branch,f.box,f.batch].join('|'))}</select></label><label class="check"><input type="checkbox" data-failure-included ${f.includedInCoupons?'checked':''}>Estaba incluido en los cupones del PDF de este cierre (aunque NO esté en el importe acreditado ingresado)</label><button type="button" class="button" data-delete-failure="${esc(f.id)}">Eliminar registro</button></div>`).join('')||'<p>No hay cobros no efectuados registrados.</p>'}<label class="check"><input id="couponConfirm" type="checkbox" required ${st.complete?'checked':''}>Corroboré la suma de los turnos con las acreditaciones y los cobros no efectuados del día</label><button class="button primary">Corroborar total de cupones y guardar</button><button id="saveCouponDraft" type="button" class="button">Guardar reparto pendiente</button></form><form id="failedForm"><h3>Registrar otro cobro no efectuado</h3><div class="formgrid"><label>Medio<select id="failedMethod"><option>Cuenta DNI</option><option>Mercado Pago</option><option>Otro electrónico</option></select></label><label>Importe ($)<input id="failedAmount" inputmode="decimal" required></label><label>Cierre responsable<select id="failedClose">${options('')}</select></label><label>Ticket (opcional)<input id="failedTicket" maxlength="100"></label><label>Motivo / referencia<input id="failedNote" maxlength="500" required></label></div><button class="button">Guardar cobro no efectuado</button></form><p>Registrar un cobro no efectuado conserva la venta original. El efectivo de ventas se calcula como ventas menos electrónicos acreditados y cobros no efectuados. El efectivo esperado al cierre incorpora el fondo inicial y resta los alivios / retiros. Se conservan el saldo del PDF y el resultado corroborado por turno.</p></div>`;}
function bindCoupons(date){if($('editCouponSummary'))$('editCouponSummary').onclick=()=>{couponEditing.add(date);drawDay();};if(!$('couponForm'))return;bindAllocationInputs(date);$('couponForm').onsubmit=e=>{e.preventDefault();try{const amounts=['couponMP','couponDNI','couponOther'].map(id=>cents($(id).value));if(amounts.some(v=>v<0)||!$('couponConfirm').checked)throw Error('Ingresá importes positivos o cero y corroborá las acreditaciones');const candidate=structuredClone(state);for(const el of $('couponForm').querySelectorAll('[data-failure]')){const f=candidate.failedPayments.find(f=>f.id===el.dataset.failure),[branch='',box='',batch='']=el.querySelector('[data-failure-close]').value.split('|');Object.assign(f,{branch,box,batch,includedInCoupons:el.querySelector('[data-failure-included]').checked});if(f.includedInCoupons&&!batch)throw Error('Asigná un cierre al cobro no efectuado incluido en cupones');}const allocations=readAllocations(false);const record={date,allocations,dailyReference:dailyReference(date),mercadoPago:amounts[0],cuentaDni:amounts[1],other:amounts[2],note:$('couponNote').value.trim(),verified:true,signature:couponSignature(candidate,date)};const i=candidate.couponReviews.findIndex(r=>r.date===date);if(i<0)candidate.couponReviews.push(record);else candidate.couponReviews[i]=record;const check=couponStatus(candidate,date);if(['mercadoPago','cuentaDni','other'].some((k,i)=>allocations.reduce((n,a)=>n+a[k],0)!==amounts[i]))throw Error('Los totales del día deben coincidir con el reparto por turno');if(!withinTolerance(check.remaining))throw Error('Los acreditados, los pedidos a cobrar y los cobros no efectuados incluidos deben sumar los cupones declarados. Diferencia: '+money(check.remaining));if(!check.complete)throw Error('Completá los cierres y el reparto de cada turno antes de corroborar el día');state=candidate;couponEditing.delete(date);clearTimeout(couponAutosave);state.completedDays=state.completedDays.filter(d=>d!==date);save('✓ Reparto corroborado');}catch(err){msg(err.message)}};$('failedForm').onsubmit=e=>{e.preventDefault();try{const amount=cents($('failedAmount').value);if(amount<=0)throw Error('El importe debe ser mayor a cero');const [branch='',box='',batch='']=$('failedClose').value.split('|');state.failedPayments.push({id:crypto.randomUUID(),date,method:$('failedMethod').value,amount,branch,box,batch,ticket:$('failedTicket').value.trim(),note:$('failedNote').value.trim(),includedInCoupons:false});state.completedDays=state.completedDays.filter(d=>d!==date);save();}catch(err){msg(err.message)}};document.querySelectorAll('[data-delete-failure]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este cobro no efectuado? Se deberá corroborar nuevamente el día.')){state.failedPayments=state.failedPayments.filter(f=>f.id!==b.dataset.deleteFailure);state.completedDays=state.completedDays.filter(d=>d!==date);save();}});}

function dailyReference(date){const r=state.couponReviews.find(r=>r.date===date);return r?.dailyReference||(!r?.allocations&&r?{mercadoPago:r.mercadoPago,cuentaDni:r.cuentaDni,other:r.other}:undefined);}
function readAllocations(draft){const date=$('date').value,previous=couponStatus(state,date).review?.allocations||[],automatic=allTurns(state,date).filter(t=>t.box!=='0001').map(t=>previous.find(a=>turnKey(a)===turnKey(t))||{branch:t.branch,box:t.box,batch:t.batch,mercadoPago:0,cuentaDni:0,other:0,pendingOrders:0});return automatic.concat([...$('couponForm').querySelectorAll('[data-coupon-turn]')].map(el=>{const [branch,box,batch]=el.dataset.couponTurn.split('|'),a={branch,box,batch};for(const k of ['mercadoPago','cuentaDni','other','pendingOrders']){const raw=el.querySelector('[data-allocation="'+k+'"]').value.trim();if(!raw&&!draft)throw Error('Completá los importes de todas las cajas y turnos; ingresá 0 cuando corresponda');a[k]=raw?cents(raw):0;if(a[k]<0)throw Error('Los importes deben ser positivos o cero');}return a;}));}
function bindAllocationInputs(date){const update=event=>{try{if(event){$('couponConfirm').checked=false;const saved=document.querySelector('[data-coupon-saved]');if(saved)saved.hidden=true;}const allocations=readAllocations(true),total=k=>allocations.reduce((n,a)=>n+a[k],0),format=n=>(n/100).toFixed(2).replace('.',',');$('couponMP').value=format(total('mercadoPago'));$('couponDNI').value=format(total('cuentaDni'));$('couponOther').value=format(total('other'));for(const [id,k] of [['couponMP','mercadoPago'],['couponDNI','cuentaDni'],['couponOther','other']])$(id+'Display').textContent=money(total(k));const candidate=structuredClone(state),old=candidate.couponReviews.find(r=>r.date===date)||{},draft={...old,date,allocations,mercadoPago:total('mercadoPago'),cuentaDni:total('cuentaDni'),other:total('other'),note:$('couponNote').value.trim(),signature:couponSignature(candidate,date),verified:false},i=candidate.couponReviews.findIndex(r=>r.date===date);if(i<0)candidate.couponReviews.push(draft);else candidate.couponReviews[i]=draft;for(const el of $('couponForm').querySelectorAll('[data-failure]')){const f=candidate.failedPayments.find(f=>f.id===el.dataset.failure),[branch='',box='',batch='']=el.querySelector('[data-failure-close]').value.split('|');Object.assign(f,{branch,box,batch,includedInCoupons:el.querySelector('[data-failure-included]').checked});}const st=couponStatus(candidate,date);$('couponDraftPreview').innerHTML='<p class="notice '+(withinTolerance(st.remaining)&&allocations.length===allTurns(candidate,date).length?'success':'')+'">'+(withinTolerance(st.remaining)?'✓ Diferencia dentro del margen de $40. ':'')+'Reparto ingresado: '+money(st.credited)+' acreditados + '+money(st.failed)+' no efectuados + '+money(st.pendingOrders)+' pedidos pendientes de cobro. Por conciliar: '+money(st.remaining)+'.</p>';for(const el of $('couponForm').querySelectorAll('[data-coupon-turn]')){const t=allTurns(candidate,date).find(t=>turnKey(t)===el.dataset.couponTurn),c=turnCollection(candidate,t);el.querySelector('[data-turn-preview]').innerHTML='<p class="notice '+(withinTolerance(c.couponDifference)?'success':'')+'"><b>'+ (c.couponDifference>0?'Declarado de más: ':c.couponDifference<0?'Falta declarar: ':'✓ Cupones conciliados: ')+money(Math.abs(c.couponDifference))+'</b> · Caja '+esc(t.box)+' · Vuelco '+esc(t.batch)+'</p><p>Pedidos pendientes de cobro: '+money(c.pendingOrders)+'. Se conservan como ventas a cobrar, separados de acreditaciones y faltantes. Confirmá su pago después en Google Sheets, pestaña «Pedidos a cobrar».</p>'+table(['Efectivo ventas calculado','No efectuados','Fondo inicial','Alivios / retiros','Efectivo esperado al cierre','Efectivo contado','Diferencia efectivo','Saldo total'],[[money(c.cashSales),money(c.failed),money(t.opening),money(t.withdrawals),money(c.expectedCash),money(t.cash),money(c.cashDifference),money(t.cash+c.credited+c.pendingOrders+t.withdrawals-t.opening-t.sales)]])+'<p>Vista previa. Los cobros no efectuados se muestran separados del efectivo; el saldo total los considera como dinero no recibido.</p>';}if(event){state=candidate;state.completedDays=state.completedDays.filter(d=>d!==date);localStorage.setItem('sashaControlCajasV1',JSON.stringify(state));localStorage.setItem('cajasPending','true');localStorage.setItem('cajasRevision',revision);clearTimeout(couponAutosave);couponAutosave=setTimeout(()=>{saveFeedback='Borrador de cupones guardado';syncGoogle();},1200);}}catch(e){$('couponDraftPreview').textContent=e.message;}};$('couponForm').querySelectorAll('[data-allocation]').forEach(el=>el.oninput=update);$('couponForm').querySelectorAll('[data-failure-included],[data-failure-close]').forEach(el=>el.onchange=update);$('couponNote').oninput=update;update();$('saveCouponDraft').onclick=()=>{try{const candidate=structuredClone(state);for(const el of $('couponForm').querySelectorAll('[data-failure]')){const f=candidate.failedPayments.find(f=>f.id===el.dataset.failure),[branch='',box='',batch='']=el.querySelector('[data-failure-close]').value.split('|');Object.assign(f,{branch,box,batch,includedInCoupons:el.querySelector('[data-failure-included]').checked});if(f.includedInCoupons&&!batch)throw Error('Asigná un cierre al cobro no efectuado incluido en PDF');}const allocations=readAllocations(true),old=state.couponReviews.find(r=>r.date===date)||{},record={date,allocations,dailyReference:dailyReference(date),mercadoPago:allocations.reduce((n,a)=>n+a.mercadoPago,0),cuentaDni:allocations.reduce((n,a)=>n+a.cuentaDni,0),other:allocations.reduce((n,a)=>n+a.other,0),note:$('couponNote').value.trim(),verified:false,signature:couponSignature(candidate,date)},i=candidate.couponReviews.findIndex(r=>r.date===date);if(i<0)candidate.couponReviews.push(record);else candidate.couponReviews[i]=record;state=candidate;state.completedDays=state.completedDays.filter(d=>d!==date);save();}catch(e){msg(e.message)}};}

function collectionsTable(turns){return `<div class="panel"><details class="report-detail"><summary>Cobros y efectivo por turno</summary>${table(['Cajera','Caja','Vuelco','Mercado Pago','Cuenta DNI','Otros','No efectuados','Efectivo de ventas','Fondo inicial','Alivios / retiros','Efectivo esperado al cierre','Efectivo contado','Diferencia efectivo','Saldo total','Estado'],turns.map(t=>{const c=turnCollection(state,t),a=c.allocation,b=closingBalance(state,t);return [esc(assign(state,t,'close').name),esc(t.box),esc(t.batch),a?money(a.mercadoPago):'—',a?money(a.cuentaDni):'—',a?money(a.other):'—',money(c.failed),c.verified?money(c.cashSales):'Pendiente',money(t.opening),money(t.withdrawals),c.verified?money(c.expectedCash):'Pendiente',money(t.cash),c.verified?money(c.cashDifference):'Pendiente',money(b.net),c.verified?'<strong class="status-ok">✓ Corroborado</strong>':'Reparto pendiente'];}))}<p>Efectivo de ventas = ventas − electrónicos acreditados − cobros no efectuados. Efectivo esperado = fondo inicial + efectivo de ventas − alivios / retiros. El saldo total compara todo el dinero efectivamente recibido con la venta.</p></details></div>`;}

function correctionValue(r,field,original=false){const source={cash:'sourceCash',opening:'sourceOpening',digital:'sourceDigital',withdrawals:'sourceWithdrawals',closingWithdrawal:'sourceClosingWithdrawal'};return field==='remainder'?remainingCash(original?{...r,cash:r.sourceCash??r.cash,closingWithdrawal:r.sourceClosingWithdrawal??r.closingWithdrawal}:r):original?(r[source[field]]??r[field]):r[field];}
function correctionControl(r,type){const targets=type==='opening'?[...(r.previous?[{r:r.previous,field:'remainder',label:'Efectivo que quedó en caja al cierre anterior · '+assign(state,r.previous,'close').name+' · '+fmt(r.previous.date)+' · Vuelco '+r.previous.batch}]:[]),{r,field:'opening',label:'Fondo de apertura de este turno · '+assign(state,r,'close').name+' · Vuelco '+r.batch}]:[{r,field:'digital',label:'Cupones declarados de este turno'},{r,field:'cash',label:'Efectivo contado al cierre de este turno'},{r,field:'opening',label:'Fondo de apertura de este turno'},{r,field:'withdrawals',label:'Alivio / retiro registrado durante el turno'},...(r.closingWithdrawal!==undefined?[{r,field:'closingWithdrawal',label:'Retiro de efectivo por cierre (último retiro)'}]:[])];const changed=targets.filter(t=>correctionValue(t.r,t.field)!==correctionValue(t.r,t.field,true));return `<div data-correction-widget>${changed.map(t=>`<p class="notice success">✓ Corrección aplicada: ${esc(t.label)} · ${money(correctionValue(t.r,t.field))}</p>${['withdrawals','closingWithdrawal'].includes(t.field)?'':`<button type="button" class="button" data-correction-undo="${esc(correctionKey(t.r)+'|'+t.field)}">Deshacer corrección</button>`}` ).join('')}<button class="button" type="button" data-correction-open>${changed.length?'Editar corrección':'Corregir importe'}</button><div data-correction-editor hidden><label>Qué importe corregir<select data-correction-target>${targets.map(t=>`<option value="${esc(correctionKey(t.r)+'|'+t.field)}">${esc(t.label)}</option>`).join('')}</select></label><p data-correction-current></p><div data-relief-original hidden><label>Importe del alivio que se registró ($)<input data-relief-before inputmode="decimal" placeholder="Ejemplo: 100000,00"></label><p>Ingresá solo el alivio equivocado. Se reemplaza por el importe correcto, conservando los demás retiros y gastos.</p></div><label>Importe correcto ($)<input data-correction-amount inputmode="decimal"></label><label>Motivo de la corrección<textarea data-correction-note rows="3" maxlength="2000" placeholder="Indicá por qué el importe registrado estaba mal"></textarea></label><div data-correction-photo hidden><p>Foto obligatoria para justificar la corrección del alivio.</p><div class="actions"><label class="button">Sacar foto<input type="file" accept="image/*" capture="environment" data-correction-camera hidden></label><label class="button">Adjuntar foto del teléfono<input type="file" accept="image/jpeg,image/png,image/webp" data-correction-gallery hidden></label></div><p data-correction-photo-name></p></div><button class="button primary" type="button" data-correction-save>Guardar corrección y recalcular</button></div></div>`;}
function bindCorrectionButtons(){document.querySelectorAll('[data-correction-widget]').forEach(el=>{let photo=null;for(const input of el.querySelectorAll('[data-correction-camera],[data-correction-gallery]'))input.onchange=()=>{photo=input.files[0]||null;el.querySelector('[data-correction-photo-name]').textContent=photo?'Foto seleccionada: '+photo.name:'';};const update=()=>{const [date,branch,box,batch,field]=el.querySelector('[data-correction-target]').value.split('|'),row=allTurns(state,date).find(r=>r.branch===branch&&r.box===box&&r.batch===batch);if(!row)return;el.querySelector('[data-correction-photo]').hidden=!['withdrawals','closingWithdrawal'].includes(field);el.querySelector('[data-relief-original]').hidden=field!=='withdrawals';const original=correctionValue(row,field,true);el.querySelector('[data-correction-current]').textContent='Cajera: '+assign(state,row,'close').name+' · Caja '+box+' · Actual: '+money(correctionValue(row,field))+' · Original: '+money(original);el.querySelector('[data-correction-amount]').value=field==='withdrawals'?'':(correctionValue(row,field)/100).toFixed(2).replace('.',',');};el.querySelector('[data-correction-open]').onclick=()=>{el.querySelector('[data-correction-editor]').hidden=false;update();el.querySelector('[data-correction-amount]').focus();};el.querySelector('[data-correction-target]').onchange=update;el.querySelector('[data-correction-save]').onclick=async()=>{const button=el.querySelector('[data-correction-save]');try{const [date,branch,box,batch,field]=el.querySelector('[data-correction-target]').value.split('|'),candidate=structuredClone(state);const row=allTurns(candidate,date).find(r=>r.branch===branch&&r.box===box&&r.batch===batch),amount=cents(el.querySelector('[data-correction-amount]').value),note=el.querySelector('[data-correction-note]').value.trim();if(!note)throw Error('Ingresá el motivo de la corrección');if(amount<0)throw Error('Ingresá un importe válido');let after=field==='remainder'?amount+row.cash-remainingCash(row):amount,reason=field==='remainder'?'Corrección del efectivo que quedó en caja al cierre: '+note:note,receipt;if(['withdrawals','closingWithdrawal'].includes(field)){if(!photo||!photo.type.startsWith('image/'))throw Error('Adjuntá una foto de respaldo antes de guardar el alivio');if(field==='withdrawals'){const raw=el.querySelector('[data-relief-before]').value.trim();if(!raw)throw Error('Ingresá el importe del alivio que se registró por error');const before=cents(raw);if(before<=0||before>row.withdrawals-(row.expenses||[]).reduce((n,e)=>n+e.amount,0))throw Error('El alivio indicado supera los retiros disponibles o incluye gastos');if(before===amount)throw Error('El importe correcto debe ser distinto al registrado');after=row.withdrawals-before+amount;reason='Alivio registrado: '+money(before)+' · Alivio correcto: '+money(amount)+' · '+note;}if(after<0||after===row[field])throw Error('Ingresá una corrección válida');button.disabled=true;msg('Guardando foto de la corrección…',true);receipt=await uploadReceipt(await receiptFile(photo));if(JSON.stringify(state)!==JSON.stringify(candidate))throw Error('Los datos cambiaron mientras se guardaba la foto. Revisá e intentá nuevamente');}addClosingCorrection(candidate,{date,branch,box,batch,field:field==='remainder'?'cash':field,after,note:reason,receipt});state=candidate;save('✓ Corrección guardada y saldos recalculados');}catch(e){msg(e.message)}finally{button.disabled=false;}};el.querySelectorAll('[data-correction-undo]').forEach(button=>button.onclick=()=>{try{const [date,branch,box,batch,field]=button.dataset.correctionUndo.split('|'),candidate=structuredClone(state),row=allTurns(candidate,date).find(r=>r.branch===branch&&r.box===box&&r.batch===batch),after=field==='remainder'?(row.sourceCash??row.cash):correctionValue(row,field,true);addClosingCorrection(candidate,{date,branch,box,batch,field:field==='remainder'?'cash':field,after,note:'Corrección deshecha: se restaura el importe original del PDF'});state=candidate;save('✓ Corrección deshecha y saldos recalculados');}catch(e){msg(e.message)}});});}
function correctionHistory({month='',cashierId='',box=''}={}){const rows=state.closingCorrections.filter(c=>(!month||c.date.startsWith(month))&&(!box||c.box===box)&&(!cashierId||(cashierId==='unassigned'?!c.cashierId:c.cashierId===cashierId))).slice().sort((a,b)=>b.changedAt.localeCompare(a.changedAt));return `<details class="panel management-section"><summary>Historial de correcciones de importes · Ver desglose</summary>${rows.length?table(['Día','Cajera','Caja','Vuelco','Campo','Original PDF','Antes','Correcto','Motivo','Registrado el','Foto justificativa'],rows.map(c=>[fmt(c.date),esc(c.cashier),esc(c.box),esc(c.batch),c.field==='cash'?'Efectivo al cierre':c.field==='digital'?'Cupones declarados':c.field==='withdrawals'?'Alivios / retiros del turno':c.field==='closingWithdrawal'?'Retiro por cierre':'Fondo inicial',money(c.sourceValue),money(c.before),money(c.after),esc(c.note),esc(new Date(c.changedAt).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'})),c.receipt?`<a class="button" href="./api/expense-receipt?id=${esc(c.receipt.id)}" target="_blank" rel="noopener">Ver foto</a>`:'—'])):'<p>No hay correcciones para estos filtros.</p>'}<p>El PDF original se conserva. Cada corrección recalcula los cierres, los acumulados y la apertura siguiente.</p></details>`;}

function monetaryInput(el){return el instanceof HTMLInputElement&&el.getAttribute('inputmode')==='decimal'&&!el.name.includes('Tickets');}
function formatAmountTyping(el){const raw=el.value;if(!raw.trim())return;const position=el.selectionStart??raw.length,digitsBefore=(raw.slice(0,position).match(/\d/g)||[]).length,commaBefore=raw.slice(0,position).includes(','),clean=raw.replace(/[^\d,]/g,''),parts=clean.split(','),whole=(parts[0]||'0').replace(/^0+(?=\d)/,'');el.value='$ '+whole.replace(/\B(?=(\d{3})+(?!\d))/g,'.')+(parts.length>1?','+(parts[1]||'').slice(0,2):'');let seen=0,caret=el.value.length;for(let i=0;i<el.value.length;i++){if(/\d/.test(el.value[i]))seen++;if(seen===digitsBefore&&digitsBefore>0){caret=i+1;break;}}if(commaBefore){const comma=el.value.indexOf(',');caret=Math.max(caret,comma+1);}el.setSelectionRange(caret,caret);}
document.addEventListener('input',e=>{if(monetaryInput(e.target))formatAmountTyping(e.target);},true);
document.addEventListener('focusout',e=>{if(monetaryInput(e.target)&&e.target.value.trim()){try{e.target.value=money(cents(e.target.value));}catch{}}});

function drawClosedDays(){$('closedDayList').innerHTML=state.closedDays.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`<div class="row"><div><b>${fmt(d.date)}</b><p>${esc(d.reason)} · No requiere informes</p></div><button type="button" class="button" data-reopen-day="${esc(d.date)}">Volver a día laborable</button></div>`).join('')||'<p>No hay feriados ni cierres especiales registrados.</p>';$('closedDayList').querySelectorAll('[data-reopen-day]').forEach(b=>b.onclick=()=>{state.closedDays=state.closedDays.filter(d=>d.date!==b.dataset.reopenDay);save('Día habilitado');});}
$('closedDayForm').onsubmit=e=>{e.preventDefault();const date=$('closedDayDate').value,reason=$('closedDayReason').value.trim();if(!date||!reason)return msg('Ingresá fecha y motivo');if(state.reports.some(r=>r.date===date)||state.manual.some(r=>r.date===date))return msg('Ese día tiene registros. Revisá su fecha antes de marcarlo sin actividad');state.closedDays=state.closedDays.filter(d=>d.date!==date);state.closedDays.push({date,reason});state.completedDays=state.completedDays.filter(d=>d!==date);save('Día sin actividad guardado');};

function drawTeamAccess(){drawTeamLink();$('teamAccessList').innerHTML=state.cashiers.filter(c=>c.active).map(c=>`<form data-team-account="${esc(c.id)}" class="panel"><h3>${esc(c.name)}</h3><label>Usuario<input name="username" value="${esc(c.id)}" pattern="[-a-z0-9_.]{3,40}" required></label><button class="button" type="submit">Guardar usuario</button></form>`).join('');$('teamAccessList').querySelectorAll('[data-team-account]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const response=await fetch('./api/team-access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cashierId:form.dataset.teamAccount,username:form.elements.username.value.trim().toLowerCase()})}),result=await apiJSON(response);if(!response.ok)throw Error(result.error);drawTeamLink();msg('Usuario guardado',true);}catch(e){msg(e.message);}finally{button.disabled=false;}});}
function teamDayPanel(date){const entries=visibleTeamDeclarations(state,date),pending=pendingTeamExpenses(state,date);if(!entries.length)return '';return `<div class="panel" id="teamDayPanel"><h2>Envíos de las cajeras · ${fmt(date)} · ${entries.length}</h2><p>Cupones y pedidos cargados por ellas. Verificá el reparto y corroborá los cupones antes de confirmar el día.</p>${entries.map(s=>`<p><b>${esc(s.cashier)}</b> · ${s.shift==='cover'?'Cubrir por ausencia':esc(s.shift)} · ${esc(s.start)} a ${esc(s.end)} · Cierre: ${fmt(s.date)}</p><p><small>Enviado: ${new Date(s.sentAt).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'})}</small></p>${table(['Caja','Mercado Pago','Cuenta DNI','Otros','Pedidos'],s.boxes.map(b=>[esc(b.box),money(b.mercadoPago),money(b.cuentaDni),money(b.other),money(b.pendingOrders)]))}<small>${state.teamApplied.some(key=>key.startsWith(s.id+'|')&&!key.endsWith('|attendance'))?teamPaymentStatus(s):'Recibido · Pendiente de vincular al cierre de su turno'}</small>${s.boxes.flatMap(b=>b.expenses.map(e=>`<p>Gasto del local · Caja ${esc(b.box)} · ${money(e.amount)} · ${esc(e.description)}${e.receipt?' · Comprobante adjunto':' · Sin comprobante (opcional)'}</p>`)).join('')}${teamEditForm(s)}` ).join('')}${pending.map((e,i)=>`<div class="panel"><b>Gasto pendiente de vincular · ${money(e.amount)}</b><p>${esc(e.cashier)} · Caja ${esc(e.box)} · ${esc(e.description)}</p><a class="button" href="./api/expense-receipt?id=${esc(e.receipt.id)}" target="_blank">Ver comprobante</a><label>Gasto del PDF<select data-team-expense="${i}"><option value="">Seleccionar gasto</option>${storeExpenses(state,date).filter(x=>x.box===e.box).map(x=>`<option value="${esc(x.key)}">${esc(x.description)} · ${money(x.amount)}</option>`).join('')}</select></label><button class="button" type="button" data-team-expense-save="${i}">Vincular comprobante</button></div>`).join('')}</div>`;}
function bindTeamExpenseLinks(date){const pending=pendingTeamExpenses(state,date);document.querySelectorAll('[data-team-expense-save]').forEach(button=>button.onclick=()=>{const e=pending[Number(button.dataset.teamExpenseSave)],key=button.parentElement.querySelector('[data-team-expense]').value,expense=storeExpenses(state,date).find(x=>x.key===key);if(!expense)return msg('Seleccioná el gasto del PDF');if(expense.amount!==e.amount)return msg('Los importes no coinciden. Revisá el gasto antes de vincular');state.expenseReceipts=state.expenseReceipts.filter(r=>r.expenseKey!==key);state.expenseReceipts.push({...e.receipt,expenseKey:key});state.completedDays=state.completedDays.filter(d=>d!==date);save('Comprobante de cajera vinculado');});}
let loadingTeam=false;async function loadTeamInbox(){if(loadingTeam)return;loadingTeam=true;try{const response=await fetch('./api/team-inbox'),result=await apiJSON(response);if(!response.ok)throw Error(result.error);if(replaceTeamInbox(state,result.submissions))save('Declaraciones de cajeras actualizadas');else if(reconcileTeam(state))save('Declaraciones de cajeras vinculadas');}catch(e){$('teamInboxStatus').textContent='No se pudo consultar los envíos: '+e.message;}finally{loadingTeam=false;}}
$('refreshTeamInbox').onclick=loadTeamInbox;window.addEventListener('focus',loadTeamInbox);loadTeamInbox();

setInterval(()=>{if(document.visibilityState==='visible')loadTeamInbox();},30000);

function drawTeamLink(){const url=new URL('../cajeras/?api='+encodeURIComponent(ECHU.url),location.href).href;$('teamAccessOutput').innerHTML='<label>Dirección de Sasha Cajeras<input readonly id="teamLink"></label><button type="button" class="button" id="copyTeamLink">Copiar dirección de la app</button>';$('teamLink').value=url;$('copyTeamLink').onclick=async()=>{try{await navigator.clipboard.writeText(url);msg('Dirección copiada',true);}catch{$('teamLink').focus();$('teamLink').select();msg('Dirección seleccionada. Mantené presionado para copiar.');}};}

function pendingTeamCoupons(date){const t=teamDeclarationTotals(state,date),declared=dailyCloses(state,date).reduce((n,r)=>n+r.digital,0),total=t.mercadoPago+t.cuentaDni+t.other+t.pendingOrders;return `<div class="panel" id="couponSummary"><h2>Cupones recibidos de las cajeras</h2><p class="notice">Los importes ya llegaron y están guardados. Faltan los PDF de cierre por turno para vincularlos y corroborarlos. No hace falta volver a cargarlos.</p><div class="cards">${card('Cupones declarados en PDF',money(declared))}${card('Acreditaciones recibidas',money(t.mercadoPago+t.cuentaDni+t.other))}${card('Pedidos pendientes',money(t.pendingOrders))}${card('Diferencia por revisar',money(declared-total),'Pendiente de vincular con los cierres de turno')}</div>${table(['Cajera','Turno','Caja','Mercado Pago','Cuenta DNI','Otros','Pedidos'],t.declarations.map(({submission:s,box:b})=>[esc(s.cashier),s.shift==='cover'?'Cubrir por ausencia':esc(s.shift),esc(b.box),money(b.mercadoPago),money(b.cuentaDni),money(b.other),money(b.pendingOrders)]))}<p>Si hay un envío de prueba o de otro turno, revisalo antes de confirmar. Los envíos anteriores se conservan en el historial.</p></div>`;}

function teamEditForm(s){return `<details class="report-detail"><summary>Editar declaración</summary><form data-team-edit="${esc(s.id)}"><label>Turno<select name="shift">${(s.shift==='cover'?['cover']:['mañana','tarde']).map(k=>`<option value="${k}" ${k===s.shift?'selected':''}>${k==='cover'?'Cubrir por ausencia':k}</option>`).join('')}</select></label>${teamEditableBoxes(s).map((b,i)=>`<fieldset data-team-box="${i}"><legend>Caja ${esc(b.box)}</legend><div class="formgrid">${[['mercadoPago','Mercado Pago'],['cuentaDni','Cuenta DNI'],['other','Otros electrónicos'],['pendingOrders','Pedidos pendientes de cobro']].map(([k,label])=>`<label>${label} ($)<input name="${k}" inputmode="decimal" required value="${(b[k]/100).toFixed(2).replace('.',',')}"></label>`).join('')}</div>${b.expenses.map((e,j)=>`<div data-team-edit-expense="${j}"><label>Gasto ($)<input name="expenseAmount" inputmode="decimal" required value="${(e.amount/100).toFixed(2).replace('.',',')}"></label><label>Motivo<input name="expenseDescription" maxlength="200" required value="${esc(e.description)}"></label></div>`).join('')}${b.box==='0003'?`<div data-new-team-expenses></div><button class="button" type="button" data-add-team-expense>Agregar gasto del local · Caja 3</button><p>Comprobante opcional. Completá el importe y el motivo del gasto omitido.</p>`:''}</fieldset>`).join('')}<label>Observaciones<textarea name="note" maxlength="500">${esc(s.note||'')}</textarea></label><button class="button" type="submit">Guardar cambios</button></form></details><button class="button" type="button" data-team-delete="${esc(s.id)}">Borrar declaración</button>`;}
async function changeTeamSubmission(s,action,changes={}){const response=await fetch('./api/team-inbox',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:s.id,expected:JSON.stringify(s),action,...changes})}),result=await apiJSON(response);if(!response.ok)throw Error(result.error);replaceTeamInbox(state,result.submissions);save(action==='delete'?'Declaración borrada. Ya pueden volver a cargarla':'Declaración corregida. Revisá y corroborá los cupones');}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-team-delete]');if(!button)return;const s=state.teamSubmissions.find(s=>s.id===button.dataset.teamDelete);if(!s||!confirm('¿Borrar la declaración de '+s.cashier+' del '+s.date+' ('+s.shift+')? Podrá volver a cargarla.'))return;button.disabled=true;try{await changeTeamSubmission(s,'delete');}catch(e){msg(e.message);}finally{button.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-team-edit]');if(!form)return;event.preventDefault();const s=state.teamSubmissions.find(s=>s.id===form.dataset.teamEdit);if(!s)return;const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const boxes=teamEditableBoxes(s);form.querySelectorAll('[data-team-box]').forEach(el=>{const box=boxes[Number(el.dataset.teamBox)];for(const k of ['mercadoPago','cuentaDni','other','pendingOrders'])box[k]=cents(el.querySelector('[name="'+k+'"]').value);el.querySelectorAll('[data-team-edit-expense]').forEach(e=>{const expense=box.expenses[Number(e.dataset.teamEditExpense)];expense.amount=cents(e.querySelector('[name="expenseAmount"]').value);expense.description=e.querySelector('[name="expenseDescription"]').value.trim();});el.querySelectorAll('[data-new-team-expense]').forEach(e=>{const amount=cents(e.querySelector('[name="newExpenseAmount"]').value),description=e.querySelector('[name="newExpenseDescription"]').value.trim();if(!amount&&!description)return;if(amount<=0||!description)throw Error('Completá importe y motivo del gasto de caja 3');box.expenses.push({amount,description,box:'0003'});});});await changeTeamSubmission(s,'edit',{boxes:boxes.filter(b=>s.boxes.some(old=>old.box===b.box)||b.expenses.length||['mercadoPago','cuentaDni','other','pendingOrders'].some(k=>b[k])),shift:form.elements.shift.value,note:form.elements.note.value.trim()});}catch(e){msg(e.message);}finally{button.disabled=false;}});

function teamPaymentStatus(s){const turns=allTurns(state,s.date).filter(t=>state.teamApplied.includes(s.id+'|'+turnKey(t))),review=state.couponReviews.find(r=>r.date===s.date);if(turns.length&&turns.every(t=>automaticTurnMatch(state,t,review?.allocations?.find(a=>turnKey(a)===turnKey(t)))))return '✓ Mercado Pago y Cuenta DNI conciliados con el PDF';if(turns.some(t=>declaredPaymentMethods(t)))return 'Diferencia por revisar: M PAGO OFF declarado = Mercado Pago; Cupones declarados = Cuenta DNI';return 'Vinculado al cierre · Revisar cupones';}


function teamEditableBoxes(s){const boxes=structuredClone(s.boxes);if(!boxes.some(b=>b.box==='0003'))boxes.push({box:'0003',mercadoPago:0,cuentaDni:0,other:0,pendingOrders:0,expenses:[]});return boxes;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-add-team-expense]');if(!button)return;const box=button.closest('[data-team-box]'),list=box.querySelector('[data-new-team-expenses]');if(box.querySelectorAll('[data-team-edit-expense],[data-new-team-expense]').length>=10)return msg('Máximo 10 gastos por caja');list.insertAdjacentHTML('beforeend','<div class="panel" data-new-team-expense><label>Importe del gasto ($)<input name="newExpenseAmount" inputmode="decimal" placeholder="0,00"></label><label>Motivo<input name="newExpenseDescription" maxlength="200" placeholder="Ej.: artículos para el local"></label><button type="button" class="button" data-remove-new-team-expense>Quitar gasto nuevo</button></div>');list.lastElementChild.querySelector('input').focus();});
document.addEventListener('click',event=>{const button=event.target.closest('[data-remove-new-team-expense]');if(button)button.closest('[data-new-team-expense]').remove();});

function openSection(id){const target=$(id);if(!target)return;const view=target.closest('.view');document.querySelector('[data-tab="'+view.id+'"]').click();for(let el=target;el&&el!==view;el=el.parentElement)if(el.tagName==='DETAILS')el.open=true;}
